import { useState } from 'react';
import './ChipFilter.css';

type FilterLabel = 'All' | 'Active' | 'Archived' | 'Starred';

const FILTERS: FilterLabel[] = ['All', 'Active', 'Archived', 'Starred'];

// Owns only visual pressed state; filtering is wired by the consumer.
export function ChipFilter(): JSX.Element {
  const [pressed, setPressed] = useState<FilterLabel>('All');

  return (
    <ul className="chip-bar" role="list">
      {FILTERS.map((label) => (
        <li key={label} className="chip-bar__item">
          <button
            type="button"
            className="chip-filter-button"
            aria-pressed={pressed === label}
            onClick={() => setPressed(label)}
          >
            <span>{label}</span>
          </button>
        </li>
      ))}
    </ul>
  );
}
